import Foundation
import CoreGraphics

/// Bridge to the private SkyLight display-mode API.
///
/// `CGDisplayCopyAllDisplayModes` filters the driver's mode list before handing
/// it over: on a display macOS doesn't consider retina-class, most (sometimes all)
/// HiDPI modes are stripped out — e.g. 25 of 78 survive on a 1440p PG279Q under
/// macOS 27. The modes are not missing — they are
/// generated by the display driver and sitting in the list underneath. These
/// three symbols read that list and switch to entries in it.
///
/// All of this is unsupported API. Every call is guarded, and the tool falls back
/// to the public CoreGraphics path if the symbols ever go away.
enum CGS {

    private typealias GetNumberOfDisplayModes = @convention(c) (CGDirectDisplayID, UnsafeMutablePointer<Int32>) -> CGError
    private typealias GetDisplayModeDescription = @convention(c) (CGDirectDisplayID, Int32, UnsafeMutableRawPointer, Int32) -> CGError
    private typealias ConfigureDisplayMode = @convention(c) (CGDisplayConfigRef, CGDirectDisplayID, Int32) -> CGError

    /// Byte length of the mode descriptor this build of SkyLight expects.
    /// Reverse-engineered layout; validate descriptors and fall back if it stops matching.
    private static let descriptorLength: Int32 = 0xD4

    /// Word offsets into the descriptor, established by probing a live display
    /// against modes whose geometry the public API already reports.
    private enum Field {
        static let modeNumber = 0
        static let flags = 1
        static let pointWidth = 2
        static let pointHeight = 3
        static let bytesPerRow = 5
        static let refresh = 47      // 16.16 fixed point
        static let pixelWidth = 50
        static let pixelHeight = 51
        static let density = 52      // float
    }

    /// Modes carrying this are not offerable as a desktop size — stretched,
    /// interlaced, or otherwise driver-internal.
    private static let unusableFlag: UInt32 = 0x4000_0000

    private struct Symbols {
        let count: GetNumberOfDisplayModes
        let describe: GetDisplayModeDescription
        let configure: ConfigureDisplayMode
    }

    private static let symbols: Symbols? = {
        guard let handle = dlopen("/System/Library/PrivateFrameworks/SkyLight.framework/SkyLight", RTLD_LAZY),
              let count = dlsym(handle, "CGSGetNumberOfDisplayModes"),
              let describe = dlsym(handle, "CGSGetDisplayModeDescriptionOfLength"),
              let configure = dlsym(handle, "CGSConfigureDisplayMode")
        else { return nil }
        return Symbols(
            count: unsafeBitCast(count, to: GetNumberOfDisplayModes.self),
            describe: unsafeBitCast(describe, to: GetDisplayModeDescription.self),
            configure: unsafeBitCast(configure, to: ConfigureDisplayMode.self)
        )
    }()

    static var available: Bool { symbols != nil }

    struct RawMode {
        let number: Int32
        let pointWidth: Int, pointHeight: Int
        let pixelWidth: Int, pixelHeight: Int
        let flags: UInt32
        let refresh: Double
        let density: Float
    }

    static func modes(for display: CGDirectDisplayID) -> [RawMode] {
        guard let symbols else { return [] }
        var count: Int32 = 0
        guard symbols.count(display, &count) == .success, count > 0, count < 10000 else { return [] }

        let buffer = UnsafeMutableRawPointer.allocate(byteCount: 512, alignment: 8)
        defer { buffer.deallocate() }

        var out: [RawMode] = []
        for index in 0..<count {
            memset(buffer, 0, 512)
            guard symbols.describe(display, index, buffer, descriptorLength) == .success else { continue }
            let w = buffer.assumingMemoryBound(to: UInt32.self)

            let flags = w[Field.flags]
            guard flags & unusableFlag == 0 else { continue }

            let pixelWidth = Int(w[Field.pixelWidth])
            // Everything real is 32-bit colour; anything else is a legacy entry.
            guard pixelWidth > 0, Int(w[Field.bytesPerRow]) / pixelWidth == 4 else { continue }

            out.append(RawMode(
                number: Int32(bitPattern: w[Field.modeNumber]),
                pointWidth: Int(w[Field.pointWidth]),
                pointHeight: Int(w[Field.pointHeight]),
                pixelWidth: pixelWidth,
                pixelHeight: Int(w[Field.pixelHeight]),
                flags: flags,
                refresh: Double(w[Field.refresh]) / 65536.0,
                density: buffer.load(fromByteOffset: Field.density * 4, as: Float.self)
            ))
        }
        return out
    }

    /// Add one private mode to the caller's shared configuration transaction.
    static func configure(_ config: CGDisplayConfigRef, modeNumber: Int32, display: CGDirectDisplayID) -> CGError {
        guard let symbols else { return .notImplemented }
        return symbols.configure(config, display, modeNumber)
    }
}
